import sys
data = sys.stdin.read().split()
if data:
    n = int(data[0])
    vals = data[1:1+n]
    res = []
    l, r = 0, n - 1
    while l <= r:
        if l == r: res.append(vals[l])
        else: res.append(vals[l]); res.append(vals[r])
        l += 1; r -= 1
    print(' '.join(res))
